import TypeWriterEffect from 'react-typewriter-effect';
import Padding from 'react-bootstrap';

const TypeWriter = () => {
    return (
        <TypeWriterEffect className="pb-sm-2"
            textStyle={{
            fontFamily: 'Red Hat Display',
            color: '#FFFF',
            fontWeight: 400,
            fontSize: '1em',
            }}
            startDelay={2000}
            cursorColor="#FFFF"
            multiText={[ 
            'HTML5',
            'CSS3',
            'JavaScript',
            'SASS',
            'Python',
            'React',
            'BootStrape',
            'Visual Studios Code',
            'Git and GitHub',
            'Figma',
            'Programming Techniques',
            'Agile Methodology',
            'Linux OS',
            'Windows OS',
            'Desktop Computer Hardware'
            ]}
            multiTextDelay={1100}
            typeSpeed={50}
        />
    );
}

export default TypeWriter;
